mapper.select:
select a.id,a.album_name,a.musician_id,u.username, a.cover_url,a.release_date,a.status,c.updated_time,a.introduction from album as a left join user as u on a.musician_id=u.id left join user_collection as c on a.id=c.target_id where c.user_id=#{userId} and c.is_canceled=0
and a.id < #{lastId}
order by c.updated_time desc limit #{pageSize}
